import { type FanoutSupport, getFanoutSupport } from "./fanout-support";
import { getModelMeta } from "./models";
import { parseScrapeTargets, STATUS_TARGETS } from "./scrape-targets";

export const FANOUT_DOCS_START =
	"{/* fanout-support:start — generated by `pnpm --filter @workspace/config docs:fanout` */}";
export const FANOUT_DOCS_END = "{/* fanout-support:end */}";

const SCRAPERS = [
	["cloro", "Cloro"],
	["brightdata", "BrightData"],
	["oxylabs", "Oxylabs"],
	["searchapi", "SearchApi"],
	["olostep", "Olostep"],
	["dataforseo", "DataForSEO"],
] as const;

const SURFACES = ["chatgpt", "google-ai-mode", "google-ai-overview", "gemini", "perplexity", "copilot"];

const APIS = [
	["openai-api", "OpenAI API"],
	["anthropic-api", "Anthropic API"],
	["mistral-api", "Mistral API"],
	["openrouter", "OpenRouter"],
] as const;

const monitored = parseScrapeTargets(STATUS_TARGETS.join(",")).filter((t) => t.webSearch);

function cell(support: FanoutSupport): string {
	switch (support.status) {
		case "supported":
			return "✅";
		case "discontinued": {
			const day = new Date(`${support.since}T00:00:00Z`).toLocaleDateString("en-US", {
				month: "short",
				day: "numeric",
				year: "numeric",
				timeZone: "UTC",
			});
			return `Stopped ${day}`;
		}
		case "never":
			return "–";
		case "unknown":
			return "Unknown";
	}
}

function scraperCell(model: string, provider: string): string {
	const targets = monitored.filter((t) => t.model === model && t.provider === provider);
	if (targets.length === 0) return "Not offered";
	const unpinned = targets.find((t) => !t.version);
	const pinned = targets.find((t) => t.version);
	const base = unpinned && cell(getFanoutSupport(unpinned));
	const pinnedCell = pinned && cell(getFanoutSupport(pinned));
	if (base && pinnedCell && base !== pinnedCell) return `${base} (${pinnedCell} with a pinned model)`;
	return base || `${pinnedCell} (pinned model only)`;
}

const row = (cells: string[]) => `| ${cells.join(" | ")} |`;

function table(header: string[], rows: string[][]): string {
	const divider = header.map((_, i) => (i === 0 ? "---" : ":---:"));
	return [row(header), row(divider), ...rows.map(row)].join("\n");
}

export function fanoutSupportMarkdown(): string {
	const scrapers = table(
		["Surface", ...SCRAPERS.map(([, name]) => name)],
		SURFACES.map((model) => [getModelMeta(model).label, ...SCRAPERS.map(([id]) => scraperCell(model, id))]),
	);
	const apis = table(
		["API", "Query fan-out"],
		APIS.map(([id, name]) => {
			const statuses = new Set(monitored.filter((t) => t.provider === id).map((t) => cell(getFanoutSupport(t))));
			return [name, [...statuses].join(" / ") || "Unknown"];
		}),
	);
	return [FANOUT_DOCS_START, "", scrapers, "", apis, "", FANOUT_DOCS_END].join("\n");
}

export function withFanoutSupport(mdx: string): string {
	const start = mdx.indexOf("{/* fanout-support:start");
	const end = mdx.indexOf(FANOUT_DOCS_END);
	if (start === -1 || end === -1) throw new Error("fan-out support markers not found");
	return mdx.slice(0, start) + fanoutSupportMarkdown() + mdx.slice(end + FANOUT_DOCS_END.length);
}
